import json,os,sqlite3
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
from pathlib import Path
from store import initialize,read,save
DB=os.environ['TRIAL_DB']; initialize(DB)
class Handler(BaseHTTPRequestHandler):
    def log_message(self,*args): pass
    def reply(self,status,data):
        self.send_response(status);self.send_header('Content-Type','application/json');self.end_headers();self.wfile.write(json.dumps(data).encode())
    def do_GET(self):
        if self.path=='/api/record': return self.reply(200,read(DB))
        name={'/':'index.html','/app.js':'app.js'}.get(self.path)
        if not name:return self.reply(404,{'error':'not found'})
        self.send_response(200);self.send_header('Content-Type','text/html' if name.endswith('html') else 'text/javascript');self.end_headers();self.wfile.write(Path(name).read_bytes())
    def do_POST(self):
        if self.path!='/api/record':return self.reply(404,{'error':'not found'})
        body=json.loads(self.rfile.read(int(self.headers['Content-Length'])))
        if body.get('simulateFailure'):return self.reply(503,{'error':'Temporary failure; retry'})
        status,result=save(DB,self.headers.get('X-Trial-Actor','alice'),body.get('title'),body.get('revision'))
        self.reply(status,result)
server=ThreadingHTTPServer(('127.0.0.1',int(os.environ.get('PORT','0'))),Handler)
print(server.server_address[1],flush=True);server.serve_forever()

