class Session:
 def __init__(self,env,name,sql):
  self.p=subprocess.Popen([PSQL,'-X','-qAt','-v','ON_ERROR_STOP=1'],env=dict(env,PGAPPNAME=name),stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,bufsize=1)
  self.q=queue.Queue();self.lines=[]
  def read():
   for line in self.p.stdout:self.lines.append(line.rstrip());self.q.put(line.rstrip())
  threading.Thread(target=read,daemon=True).start();self.send(sql)
 def send(self,sql):self.p.stdin.write(sql+'\n');self.p.stdin.flush()
 def until(self,token,timeout=8):
  end=time.monotonic()+timeout
  while time.monotonic()<end:
   try:line=self.q.get(timeout=max(.01,end-time.monotonic()))
   except queue.Empty:break
   if line==token:return
  raise AssertionError(('missing barrier',token,self.lines))
 def finish(self):
  if self.p.poll() is None:self.send('COMMIT;\n\\q');self.p.wait(timeout=10)
  return self.p.returncode,self.lines,self.p.stderr.read()
 def close(self):
  if self.p.poll() is None:self.p.terminate();self.p.wait(timeout=5)

